  const output = capture ? await new Response(child.stdout).text() : "";
  const code = await child.exited;
  if (code !== 0)
    throw new Error(`\u547D\u4EE4\u5931\u8D25\uFF08\u9000\u51FA\u7801 ${code}\uFF09\uFF1A${args[0]} ${args[1]}`);
  return output;
