        diagnostics.push(`${name}: \u4EC5\u4F7F\u7528 SDK \u516C\u5F00\u7EC4\u4EF6\u5165\u53E3\uFF0C\u4E0D\u5F15\u5165\u5BBF\u4E3B\u5B9E\u73B0\u6216\u5168\u5C40\u6837\u5F0F\uFF1A${specifier}`);
