// commands/plugin.ts
async function plugin2(context) {
  const [command] = context.args;
  if (!command || command === "create" || context.args.includes("--help") || context.args.includes("-h"))
    return runPluginTool(context.args, { cwd: context.cwd, sdkArchive: join2(context.assetsDirectory, "resources/sdk/malatang-sdk.tgz"), templatesDirectory: join2(context.assetsDirectory, "resources/sdk/templates") });
  const json = context.args.includes("--json");
  const fail = (message) => {
    process.stderr.write(message + `
`);
    if (json)
      process.stdout.write(JSON.stringify({ ok: false, error: message }) + `
`);
    return 1;
  };
  if (!["check", "build", "pack"].includes(command))
    return fail("\u672A\u77E5 plugin \u547D\u4EE4\uFF1B\u8FD0\u884C malatang plugin --help");
  const bun = Bun.which("bun");
  if (!bun)
    return fail("\u7F3A\u5C11\u5F00\u53D1\u8005 Bun\uFF1B\u8BF7\u4ECE https://bun.sh \u5B89\u88C5 Bun >= 1.4.2 \u540E\u91CD\u8BD5\u3002");
  const version = Bun.spawnSync([bun, "--version"], { stdout: "pipe", stderr: "pipe" });
  const parts = version.stdout.toString().trim().match(/^(\d+)\.(\d+)\.(\d+)$/);
  if (version.exitCode !== 0 || !parts || +parts[1] < 1 || +parts[1] === 1 && (+parts[2] < 4 || +parts[2] === 4 && +parts[3] < 2))
    return fail("\u5F00\u53D1\u8005 Bun \u7248\u672C\u8FC7\u65E7\uFF1B\u8BF7\u5347\u7EA7\u5230 Bun >= 1.4.2\u3002");
  const args = context.args.slice(1).filter((arg) => arg !== "--json");
  if (args.length > 1 || args[0]?.startsWith("-"))
    return fail("\u53C2\u6570\u65E0\u6548\uFF1B\u8FD0\u884C malatang plugin --help");
  const root = resolve4(context.cwd, args[0] ?? ".");
  let entry;
  try {
    entry = createRequire2(join2(root, "package.json")).resolve("@semicoder/malatang-sdk/plugin");
  } catch {
    return fail(`\u7F3A\u5C11\u9879\u76EE\u4F9D\u8D56\uFF1B\u8BF7\u8FDB\u5165 ${root} \u540E\u8FD0\u884C bun install --ignore-scripts\u3002`);
  }
  const child = Bun.spawn([bun, entry, command, root, ...json ? ["--json"] : []], { cwd: context.cwd, env: process.env, stdin: "inherit", stdout: "inherit", stderr: "inherit" });
  return await child.exited;
}

